try{for(const path of paths)for(const theme of['light','dark'])for(const width of(stage==='before'?[360,1280]:[360,390,768,1280,1920])){
 await p.send('Emulation.setDeviceMetricsOverride',{width,height:900,deviceScaleFactor:1,mobile:width<500});await p.send('Page.navigate',{url:origin+path});await p.wait("!!document.querySelector('main h1')&&!document.querySelector('#prerender-seo')&&[...document.querySelectorAll('main h3')].some(e=>e.textContent==='Sources & further reading')");await p.evaluate('document.fonts.ready.then(()=>true)',true);await p.evaluate("[...document.querySelectorAll('button')].find(b=>b.textContent.trim()==='Reject analytics')?.click();true");await p.evaluate(`if(document.documentElement.classList.contains('light')!==${theme==='light'})[...document.querySelectorAll('button[aria-label*=theme]')].find(b=>b.getClientRects().length).click();true`);await pause(500);
 await p.evaluate("[...document.querySelectorAll('main h3')].find(e=>e.textContent==='Sources & further reading').scrollIntoView({block:'center'});true");await pause(300);
 const count=await p.evaluate("document.querySelectorAll('main a.text-emerald-400').length");assert.equal(count,3);
 for(const hover of[false,true]){
  const targets=[];for(let i=0;i<count;i++){
   await p.send('Input.dispatchMouseEvent',{type:'mouseMoved',x:2,y:110});
   if(hover){const b=await p.evaluate(`(()=>{const e=document.querySelectorAll('main a.text-emerald-400')[${i}];e.scrollIntoView({block:'center'});const r=e.getBoundingClientRect();return{x:r.x+Math.min(r.width/2,100),y:r.y+r.height/2}})()`);await p.send('Input.dispatchMouseEvent',{type:'mouseMoved',...b});}await pause(250);
   const info=await p.evaluate(`(()=>{const e=document.querySelectorAll('main a.text-emerald-400')[${i}],s=getComputedStyle(e),layers=[];for(let x=e;x;x=x.parentElement){const q=getComputedStyle(x);layers.push({background:q.backgroundColor,image:q.backgroundImage});if(q.backgroundColor.startsWith('rgb('))break;}return{text:e.textContent,href:e.getAttribute('href'),color:s.color,fontSize:s.fontSize,fontWeight:s.fontWeight,layers}})()`);let bg=[255,255,255];for(const l of[...info.layers].reverse())bg=over(rgb(l.background),bg);info.contrast=ratio(over(rgb(info.color),bg),bg);info.background=bg;targets.push(info);
  }
  await p.evaluate("[...document.querySelectorAll('main h3')].find(e=>e.textContent==='Sources & further reading').scrollIntoView({block:'center'});true");await pause(200);const n=`${path.includes('foundations')?'next':'back'}-${width}-${theme}-${hover?'hover':'rest'}.png`;await p.screenshot(folder+'/'+n);rows.push({path,width,theme,hover,targets,screenshot:n});
 }
}assert.deepEqual(errors,[]);if(stage!=='before')for(const x of rows)for(const t of x.targets)assert.ok(t.contrast>=4.5,'Link contrast '+t.text+' '+t.contrast);}catch(e){failure=e.message;throw e;}finally{writeFileSync(root+'COURSE-LINK-CONTRAST-'+stage.toUpperCase()+'-20261030.json',JSON.stringify({checkedAt:new Date().toISOString(),sha,origin,outcome:failure?'FAIL':stage==='before'?'OBSERVED_REQUIRES_REVIEW':'PASS',failure,rows,runtimeErrors:errors,blocked,scope:'Source links and next/back link text, rest and actual pointer hover, both real themes. Never activates links or quiz/progress/order/account actions. Measured CSS compositing over solid surfaces; screenshot review required.'},null,2)+'\n');await p.close();}
